def track(p):
    loaded[os.path.relpath(p, '/tmp/opensip-design-corrections')] = sha(p)
    return p


def load(name, rel):
    p = track(DC + '/' + rel)
    s = importlib.util.spec_from_file_location(name, p)
    m = importlib.util.module_from_spec(s)
    sys.modules[name] = m
    s.loader.exec_module(m)
    return m


